package com.proxyslabs.haruna.image
import java.io.File
fun main(args:Array<String>){check(NezumiImageNative.available);val root=File(args[0]);val first=NezumiImageNative.create();check(first>0);check(NezumiImageNative.validateFiles(NezumiPackage.graphFiles(root)));check(NezumiImageNative.loadCpu(first,root.path));check(NezumiImageNative.isLoaded(first));NezumiImageNative.cancel(first);check(NezumiImageNative.generateRgb(first,"a red apple","",5,424242)==null);NezumiImageNative.destroy(first);NezumiImageNative.destroy(first);check(!NezumiImageNative.isLoaded(first));val second=NezumiImageNative.create();check(second>first);NezumiImageNative.cancel(first);check(NezumiImageNative.loadCpu(second,root.path));check(NezumiImageNative.isLoaded(second));NezumiImageNative.unload(second);check(!NezumiImageNative.isLoaded(second));NezumiImageNative.destroy(second);println("PASS actual host JNI: FlatBuffer validation, CPU load, cancel before generation, destroy idempotency, stale handle, new handle load, unload")}
